with account_summary as (select account_id, round((100 * sum(case when merchant = 'Grab' then 1 else 0 end)) / count(*), 1) pct_grab, count(distinct amount) unique_txn_types from transactions where txn_time < '2025-05-01' group by account_id) select a.account_type, as.pct_grab, as.unique_txn_types from accounts a left join account_summary as on a.id = as.account_id where as.pct_grab > 28;
